@namespace sv_a88db3f46968435187e2677910e415d4.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol>
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var css = step == CurrentStep ? "active"
                    : step < CurrentStep ? "completed"
                    : "future";

            <li class="step @css">
                @if (step < CurrentStep)
                {
                    <button type="button" class="step-button" @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-icon">✓</span>
                        <span class="step-label">@StepNames[step]</span>
                    </button>
                }
                else
                {
                    <span class="step-content">
                        <span class="step-icon">@(step + 1)</span>
                        <span class="step-label">@StepNames[step]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

@namespace sv_a88db3f46968435187e2677910e415d4.Components.Pages.Apply
@using sv_a88db3f46968435187e2677910e415d4.Models

<div class="reference-form">
    <h4>Reference @(Index + 1)</h4>
    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" @bind="Reference.Name" @bind:event="oninput" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" @bind="Reference.Relationship" @bind:event="oninput" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" @bind="Reference.Email" @bind:event="oninput" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" @bind="Reference.Phone" @bind:event="oninput" />
        </div>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_a88db3f46968435187e2677910e415d4.Components.Pages.Apply
@using sv_a88db3f46968435187e2677910e415d4.Models

<section class="step-section">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" @bind="Model.FullName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" @bind="Model.Email" @bind:event="oninput" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" @bind="Model.Phone" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" @bind="Model.Address" @bind:event="oninput"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-error">@ValidationMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ValidationMessage;
    private string? EmailError;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ValidationMessage = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ValidationMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Model.Email);
            IsValidating = false;

            if (!isValid)
            {
                EmailError = "This email address is not valid.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_a88db3f46968435187e2677910e415d4.Components.Pages.Apply
@using sv_a88db3f46968435187e2677910e415d4.Models

<section class="step-section">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       CanRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
        @if (index < Entries.Count - 1)
        {
            <hr />
        }
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-error">@ValidationMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ValidationMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) ||
                string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate is null)
            {
                ValidationMessage = "Each position requires a company name, job title, and start date.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_a88db3f46968435187e2677910e415d4.Components.Pages.Apply
@using sv_a88db3f46968435187e2677910e415d4.Models

<section class="step-section">
    <h2>References</h2>
    <p class="help-text">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="References[index]"
                       Index="index"
                       CanRemove="References.Count > 2"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-error">@ValidationMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ValidationMessage = null;

        foreach (var reference in References)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) ||
                string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email))
            {
                ValidationMessage = "Each reference requires at least a name, relationship, and email.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_a88db3f46968435187e2677910e415d4.Components.Pages.Apply

<section class="step-section">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter below:</label>
        <textarea rows="12" maxlength="@MaxLength"
                  @bind="CoverLetterText"
                  @bind:event="oninput"
                  @bind:after="NotifyChanged"></textarea>
        <span class="char-count @(CoverLetterText.Length > MaxLength ? "over-limit" : "")">
            @CoverLetterText.Length / @MaxLength characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(ValidationMessage))
    {
        <div class="validation-error">@ValidationMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetterText { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> CoverLetterTextChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationMessage;

    private async Task NotifyChanged()
    {
        await CoverLetterTextChanged.InvokeAsync(CoverLetterText);
    }

    private async Task HandleNext()
    {
        ValidationMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ValidationMessage = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_a88db3f46968435187e2677910e415d4.Components.Pages.Apply
@using sv_a88db3f46968435187e2677910e415d4.Models

<section class="step-section review-section">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h3>✓ Application Submitted!</h3>
            <p>Your application has been received. Your application ID is <strong>#@ApplicationId</strong>.</p>
        </div>
    }
    else
    {
        <div class="review-block">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Model.Personal.FullName</dd>
                <dt>Email</dt><dd>@Model.Personal.Email</dd>
                <dt>Phone</dt><dd>@Model.Personal.Phone</dd>
                <dt>Address</dt><dd>@Model.Personal.Address</dd>
            </dl>
        </div>

        <div class="review-block">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in Model.WorkEntries)
            {
                <div class="review-item">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="review-date">
                        @(entry.StartDate?.ToString("MMM yyyy") ?? "N/A") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-block">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in Model.References)
            {
                <div class="review-item">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />@reference.Email @(!string.IsNullOrWhiteSpace(reference.Phone) ? $"• {reference.Phone}" : "")
                </div>
            }
        </div>

        <div class="review-block">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@Model.CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-error">@ErrorMessage</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</section>

@code {
    [Parameter, EditorRequired] public ApplicationFormModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        IsSubmitting = true;
        ErrorMessage = null;
        StateHasChanged();

        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

