@namespace sv_a88db3f46968435187e2677910e415d4.Components.Pages.Apply
@using sv_a88db3f46968435187e2677910e415d4.Models

<section class="step-section review-section">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h3>✓ Application Submitted!</h3>
            <p>Your application has been received. Your application ID is <strong>#@ApplicationId</strong>.</p>
        </div>
    }
    else
    {
        <div class="review-block">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Model.Personal.FullName</dd>
                <dt>Email</dt><dd>@Model.Personal.Email</dd>
                <dt>Phone</dt><dd>@Model.Personal.Phone</dd>
                <dt>Address</dt><dd>@Model.Personal.Address</dd>
            </dl>
        </div>

        <div class="review-block">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in Model.WorkEntries)
            {
                <div class="review-item">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="review-date">
                        @(entry.StartDate?.ToString("MMM yyyy") ?? "N/A") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-block">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in Model.References)
            {
                <div class="review-item">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />@reference.Email @(!string.IsNullOrWhiteSpace(reference.Phone) ? $"• {reference.Phone}" : "")
                </div>
            }
        </div>

        <div class="review-block">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@Model.CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-error">@ErrorMessage</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</section>

@code {
    [Parameter, EditorRequired] public ApplicationFormModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        IsSubmitting = true;
        ErrorMessage = null;
        StateHasChanged();

        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_a88db3f46968435187e2677910e415d4.Components.Pages.Apply
@using sv_a88db3f46968435187e2677910e415d4.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-wizard">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="formModel.Personal"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="formModel.WorkEntries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="formModel.References"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep @bind-CoverLetterText="formModel.CoverLetter"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Model="formModel"
                        OnBack="PreviousStep"
                        OnEditStep="GoToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private ApplicationFormModel formModel = new();
    private int currentStep;

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;
    private void GoToStep(int step) => currentStep = step;

    private async Task<int> SubmitApplication()
    {
        var application = formModel.ToRecord();
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.application-wizard {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-wizard h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator ol {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem 0;
    justify-content: space-between;
}

.step-indicator .step {
    flex: 1;
    text-align: center;
    position: relative;
}

.step-indicator .step + .step::before {
    content: "";
    position: absolute;
    top: 14px;
    left: -50%;
    width: 100%;
    height: 2px;
    background: #ddd;
    z-index: 0;
}

.step-indicator .step.completed + .step::before,
.step-indicator .step.completed + .step.active::before {
    background: #4caf50;
}

.step-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    font-size: 0.8rem;
    font-weight: bold;
    position: relative;
    z-index: 1;
}

.step.active .step-icon {
    background: #1976d2;
    color: white;
}

.step.completed .step-icon {
    background: #4caf50;
    color: white;
}

.step.future .step-icon {
    background: #e0e0e0;
    color: #999;
}

.step-label {
    display: block;
    font-size: 0.75rem;
    margin-top: 0.25rem;
    color: #666;
}

.step.active .step-label {
    color: #1976d2;
    font-weight: 600;
}

.step-button {
    background: none;
    border: none;
    cursor: pointer;
    padding: 0;
}

.step-button:hover .step-label {
    text-decoration: underline;
}

.step-content {
    display: inline-block;
}

/* Form Elements */
.step-section {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.4rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn-primary {
    background: #1976d2;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    background: #f5f5f5;
    color: #333;
    border: 1px solid #ccc;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-remove {
    background: none;
    border: none;
    color: #d32f2f;
    cursor: pointer;
    font-size: 0.85rem;
    padding: 0.25rem 0;
}

.btn-remove:hover {
    text-decoration: underline;
}

.btn-link {
    background: none;
    border: none;
    color: #1976d2;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Validation */
.validation-error {
    color: #d32f2f;
    background: #ffebee;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    margin-top: 1rem;
    font-size: 0.9rem;
}

.field-error {
    color: #d32f2f;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Character count */
.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #666;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #d32f2f;
}

/* Help text */
.help-text {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

/* Work Entry / Reference Forms */
.work-entry-form,
.reference-form {
    padding: 1rem;
    border: 1px solid #eee;
    border-radius: 6px;
    margin-bottom: 1rem;
    background: #fafafa;
}

.reference-form h4 {
    margin: 0 0 0.75rem 0;
    color: #555;
}

/* Review Section */
.review-section .review-block {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #eee;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h3 {
    margin: 0 0 0.5rem 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.3rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
}

.review-section dd {
    margin: 0;
}

.review-item {
    margin-bottom: 0.75rem;
    padding-left: 0.5rem;
    border-left: 3px solid #e0e0e0;
}

.review-date {
    font-size: 0.85rem;
    color: #666;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9f9f9;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #eee;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation h3 {
    color: #4caf50;
    font-size: 1.5rem;
}

